sys_script_fix.script:
var eventId = 'EVT0001014'; // Replace with your actual Event sys_id

var venueGR = new GlideRecord('x_1790229_event_ma_venue'); // Replace with your actual Venue table name
venueGR.addQuery('u_event_id.number', eventId); // Assuming 'u_event' is the reference field to the Event table
venueGR.query();

while (venueGR.next()) {
    gs.info('Venue Name: ' + venueGR.getValue('u_venue_name'));
    gs.info('Contact Number: ' + venueGR.getValue('u_contact_number'));
    gs.info('Contact Person: ' + venueGR.getValue('u_contact_person'));

    gs.info('Capacity: ' + venueGR.getValue('u_capacity'));

}
